-- ── the read ─────────────────────────────────────────────────────────────
create or replace function public.mcp_op_list_member_term_changes(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_member uuid := coalesce(public.mcp_uuid_arg(p_args, 'member_id', false), c.member_id);
begin
  if v_member is null then
    return public.mcp_outcome('not_found', null, 'not_found');
  end if;
  -- the app's own right: managing members, or the member's own changes
  if v_member is distinct from c.member_id and not public.has_permission(c.workspace_id, 'manageMembers') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  if not exists (select 1 from public.members m where m.id = v_member and m.workspace_id = c.workspace_id) then
    return public.mcp_outcome('not_found', null, 'not_found');
  end if;
  return public.mcp_outcome('completed', jsonb_build_object('member_id', v_member, 'items', (
    select coalesce(jsonb_agg(jsonb_build_object(
             'change_id', x.id, 'kind', x.kind, 'state', x.state, 'effective_on', x.due_on,
             'applied_on', x.applied_on, 'to_pct', x.to_pct, 'to_status', x.to_status,
             'reason', x.reason, 'group_id', x.group_id) order by x.due_on desc, x.seq desc), '[]'::jsonb)
      from (select * from public.member_term_changes t
             where t.member_id = v_member and t.workspace_id = c.workspace_id
             order by t.due_on desc, t.seq desc limit 100) x)));
end;
$fn$;
revoke execute on function public.mcp_op_list_member_term_changes(public.mcp_call_context, jsonb) from public, anon, authenticated;

-- ── what the person is asked to confirm ──────────────────────────────────
-- The member, as the other member requests show it, with the dates. The
-- command is asked, not copied: it runs here and is always rolled back.
create or replace function public.mcp_target_schedule_member_share_change(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_member public.members;
  v_name text;
  v_pct int;
  v_on date;
begin
  if coalesce(p_args->>'pct', '') !~ '^\d{1,3}$' or (p_args->>'pct')::int > 100 then
    raise exception using errcode = '22023', message = 'pct';
  end if;
  v_pct := (p_args->>'pct')::int;
  begin
    v_on := (p_args->>'effective_on')::date;
  exception when others then
    raise exception using errcode = '22023', message = 'effective_on';
  end;
  select * into v_member from public.members
   where id = public.mcp_uuid_arg(p_args, 'member_id') and workspace_id = p_workspace_id;
  if v_member.id is null then return null; end if;
  begin
    perform public.schedule_member_share_change(v_member.id, v_pct, v_on, gen_random_uuid());
    raise exception 'probe' using errcode = 'DKP01';
  exception
    when sqlstate 'DKP01' then null;
    when sqlstate 'DKN01' then
      raise exception 'not allowed to change subscriptions' using errcode = '42501';
    when sqlstate '55000' or sqlstate 'P0001' then
      raise exception 'the change is refused' using errcode = '22023';
  end;
  -- the label the person is shown: read through the one name helper, never
  -- from a profile column here (an authorization function does not read them)
  v_name := coalesce(nullif(v_member.managed_name, ''), public.mcp_person_name(v_member.user_id), '');
  return jsonb_build_object('kind', 'member', 'id', v_member.id, 'name', v_name,
    'status', v_member.status, 'subscription_pct', v_member.subscription_pct,
    'to_pct', v_pct, 'effective_on', v_on,
    'revision', md5(to_jsonb(v_member)::text || (
      select coalesce(string_agg(c.id::text || c.state, ',' order by c.seq), '')
        from public.member_term_changes c
       where c.member_id = v_member.id and c.state in ('pending', 'scheduled'))));
end;
$fn$;
revoke execute on function public.mcp_target_schedule_member_share_change(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_schedule_member_pause(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_member public.members;
  v_name text;
  v_from date;
  v_to date;
begin
  begin
    v_from := (p_args->>'from')::date;
    v_to := (p_args->>'to')::date;
  exception when others then
    raise exception using errcode = '22023', message = 'from or to';
  end;
  select * into v_member from public.members
   where id = public.mcp_uuid_arg(p_args, 'member_id') and workspace_id = p_workspace_id;
  if v_member.id is null then return null; end if;
  begin
    perform public.schedule_member_pause(v_member.id, v_from, v_to, gen_random_uuid());
    raise exception 'probe' using errcode = 'DKP01';
  exception
    when sqlstate 'DKP01' then null;
    when sqlstate 'DKN01' then
      raise exception 'not allowed to change memberships' using errcode = '42501';
    when sqlstate '55000' or sqlstate 'P0001' then
      raise exception 'the pause is refused' using errcode = '22023';
  end;
  -- the label the person is shown: read through the one name helper, never
  -- from a profile column here (an authorization function does not read them)
  v_name := coalesce(nullif(v_member.managed_name, ''), public.mcp_person_name(v_member.user_id), '');
  return jsonb_strip_nulls(jsonb_build_object('kind', 'member', 'id', v_member.id, 'name', v_name,
    'status', v_member.status, 'subscription_pct', v_member.subscription_pct,
    'from', v_from, 'to', v_to,
    'revision', md5(to_jsonb(v_member)::text || (
      select coalesce(string_agg(c.id::text || c.state, ',' order by c.seq), '')
        from public.member_term_changes c
       where c.member_id = v_member.id and c.state in ('pending', 'scheduled')))));
end;
$fn$;
revoke execute on function public.mcp_target_schedule_member_pause(uuid, jsonb) from public, anon, authenticated;

create or replace function public.mcp_target_cancel_member_term_change(p_workspace_id uuid, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_change public.member_term_changes;
  v_member public.members;
  v_name text;
begin
  select * into v_change from public.member_term_changes
   where id = public.mcp_uuid_arg(p_args, 'change_id') and workspace_id = p_workspace_id;
  if v_change.id is null then return null; end if;
  select * into v_member from public.members where id = v_change.member_id;
  -- only a change the command would cancel is put to the person
  if v_change.state not in ('pending', 'scheduled') then
    raise exception 'only a change not yet applied is cancelled' using errcode = '22023';
  end if;
  if v_change.state = 'scheduled' and v_change.due_on <= public.workspace_today(v_change.workspace_id) then
    raise exception 'this change applies today' using errcode = '22023';
  end if;
  -- the label the person is shown: read through the one name helper, never
  -- from a profile column here (an authorization function does not read them)
  v_name := coalesce(nullif(v_member.managed_name, ''), public.mcp_person_name(v_member.user_id), '');
  return jsonb_strip_nulls(jsonb_build_object('kind', 'member', 'id', v_member.id, 'name', v_name,
    'status', v_member.status, 'subscription_pct', v_member.subscription_pct,
    'change_kind', v_change.kind, 'to_pct', v_change.to_pct, 'to_status', v_change.to_status,
    'effective_on', v_change.due_on,
    'revision', md5(to_jsonb(v_change)::text)));
end;
$fn$;
revoke execute on function public.mcp_target_cancel_member_term_change(uuid, jsonb) from public, anon, authenticated;

-- ── the writes, after the person confirmed ───────────────────────────────
-- Each asks manageMembers first (the command asks it again), calls the command
-- under the caller's identity and answers its result. The commands' own
-- refusals (an earliest date, an invoiced period, a day that applies today)
-- reach the assistant as `conflict` with their reason.
create or replace function public.mcp_op_schedule_member_share_change(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_member uuid := public.mcp_uuid_arg(p_args, 'member_id');
  v_result jsonb;
begin
  if not public.has_permission(c.workspace_id, 'manageMembers') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  if not exists (select 1 from public.members m where m.id = v_member and m.workspace_id = c.workspace_id) then
    return public.mcp_outcome('not_found', null, 'not_found');
  end if;
  begin
    v_result := public.schedule_member_share_change(v_member, (p_args->>'pct')::int,
      (p_args->>'effective_on')::date, c.request_id);
  exception when sqlstate '22023' or sqlstate '55000' then
    return public.mcp_outcome('conflict', jsonb_build_object('reason', left(sqlerrm, 200)), 'refused');
  end;
  return public.mcp_member_outcome(public.mcp_request_outcome(jsonb_build_object('pending', v_result->>'state' = 'pending')),
    jsonb_strip_nulls(jsonb_build_object('change_id', v_result->'change_id', 'state', v_result->'state',
      'effective_on', v_result->'effective_on', 'event_id', v_result->'event_id',
      'replayed', v_result->'replayed')), v_member);
end;
$fn$;
revoke execute on function public.mcp_op_schedule_member_share_change(public.mcp_call_context, jsonb) from public, anon, authenticated;

create or replace function public.mcp_op_schedule_member_pause(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_member uuid := public.mcp_uuid_arg(p_args, 'member_id');
  v_result jsonb;
begin
  if not public.has_permission(c.workspace_id, 'manageMembers') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  if not exists (select 1 from public.members m where m.id = v_member and m.workspace_id = c.workspace_id) then
    return public.mcp_outcome('not_found', null, 'not_found');
  end if;
  begin
    v_result := public.schedule_member_pause(v_member, (p_args->>'from')::date, (p_args->>'to')::date, c.request_id);
  exception when sqlstate '22023' or sqlstate '55000' or sqlstate 'DKN01' then
    return public.mcp_outcome('conflict', jsonb_build_object('reason', left(sqlerrm, 200)), 'refused');
  end;
  return public.mcp_member_outcome(public.mcp_request_outcome(jsonb_build_object('pending', v_result->>'state' = 'pending')),
    jsonb_strip_nulls(jsonb_build_object('change_id', v_result->'change_id', 'state', v_result->'state',
      'event_id', v_result->'event_id', 'replayed', v_result->'replayed', 'due', v_result->'due',
      'first_free', v_result->'first_free',
      'bookings_in_free_months', v_result->'bookings_in_free_months')), v_member);
end;
$fn$;
revoke execute on function public.mcp_op_schedule_member_pause(public.mcp_call_context, jsonb) from public, anon, authenticated;

create or replace function public.mcp_op_cancel_member_term_change(c public.mcp_call_context, p_args jsonb)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_id uuid := public.mcp_uuid_arg(p_args, 'change_id');
  v_change public.member_term_changes;
  v_n integer;
begin
  if not public.has_permission(c.workspace_id, 'manageMembers') then
    return public.mcp_outcome('denied', null, 'forbidden');
  end if;
  select * into v_change from public.member_term_changes where id = v_id and workspace_id = c.workspace_id;
  if v_change.id is null then
    return public.mcp_outcome('not_found', null, 'not_found');
  end if;
  begin
    v_n := public.cancel_member_term_change(v_id);
  exception when sqlstate '22023' or sqlstate '55000' then
    return public.mcp_outcome('conflict', jsonb_build_object('reason', left(sqlerrm, 200)), 'refused');
  end;
  -- how many changes it cancelled: a grouped pause cancels both its ends
  return public.mcp_member_outcome('completed',
    jsonb_build_object('cancelled', v_n, 'change_id', v_id), v_change.member_id);
end;
$fn$;
revoke execute on function public.mcp_op_cancel_member_term_change(public.mcp_call_context, jsonb) from public, anon, authenticated;

